This smaller example ignores a reply whose ID does not match.
```typescript
type State =
  | { kind: "loading"; requestId: number }
  | { kind: "success"; requestId: number; data: string[] };
function resolve(state: State, requestId: number, data: string[]): State {
  if (state.kind !== "loading" || state.requestId !== requestId) {
    return state;
  }
  return { kind: "success", requestId, data };
}
const active: State = { kind: "loading", requestId: 8 };
console.log(resolve(active, 7, ["old"]) === active);
```
The output is true: the old reply returns the exact same state object.
